"use client";

import { ConnectionSurface, connectionTarget } from "@diax/react/connect";
import { DiagramFrame } from "@diax/ui-react/presentation";
import type { DiaxRelation } from "diax";
import type { ReactNode } from "react";

const participants = [
  { id: "operator", label: "Operator", detail: "Chooses retry" },
  { id: "host", label: "Host shell", detail: "Owns UI state" },
  { id: "runtime", label: "Federation runtime", detail: "Resolves expose" },
  { id: "remote", label: "Remote deployment", detail: "Attempt-scoped assets" },
] as const;

type ParticipantId = (typeof participants)[number]["id"];
type MessageKind = "request" | "return" | "failure" | "retry";

interface RecoveryMessage {
  id: string;
  from: ParticipantId;
  to: ParticipantId;
  label: string;
  detail: string;
  kind: MessageKind;
}

const messages = [
  {
    id: "f01-activate",
    from: "operator",
    to: "host",
    label: "Activate Connect feature",
    detail: "No remote request exists before explicit intent",
    kind: "request",
  },
  {
    id: "f02-resolve",
    from: "host",
    to: "runtime",
    label: "Resolve ./Connect",
    detail: "Host enters loading and delegates remote resolution",
    kind: "request",
  },
  {
    id: "f03-attempt-one",
    from: "runtime",
    to: "remote",
    label: "GET attempt/1/remoteEntry.mjs",
    detail: "Container and descendant chunks share one attempt base",
    kind: "request",
  },
  {
    id: "f04-unavailable",
    from: "remote",
    to: "runtime",
    label: "503 remote unavailable",
    detail: "Transport failure is classified as retryable",
    kind: "failure",
  },
  {
    id: "f05-visible-error",
    from: "runtime",
    to: "host",
    label: "Render recovery state",
    detail: "The host preserves intent and exposes one Retry action",
    kind: "return",
  },
  {
    id: "f06-retry",
    from: "operator",
    to: "host",
    label: "Retry Connect remote",
    detail: "A deliberate action starts a new deployment attempt",
    kind: "retry",
  },
  {
    id: "f07-attempt-two",
    from: "host",
    to: "remote",
    label: "GET attempt/2 container + chunk",
    detail: "The entire remote asset graph moves to the new base path",
    kind: "retry",
  },
  {
    id: "f08-ready",
    from: "remote",
    to: "host",
    label: "Mount recovered feature",
    detail: "The host renders authored DOM only after the expose is ready",
    kind: "return",
  },
] as const satisfies readonly RecoveryMessage[];

const relationColor: Record<MessageKind, string> = {
  request: "#285d67",
  return: "#687476",
  failure: "#a44135",
  retry: "#a16518",
};

const relations = messages.map((message): DiaxRelation<ReactNode> => {
  const forwards = participantIndex(message.from) < participantIndex(message.to);
  return {
    id: message.id,
    from: endpointId(message.id, message.from),
    to: endpointId(message.id, message.to),
    label: <MessageLabel index={message.id.slice(1, 3)}>{message.label}</MessageLabel>,
    sourceAnchor: forwards ? "right" : "left",
    targetAnchor: forwards ? "left" : "right",
    pathType: "straight",
    style: message.kind === "return" || message.kind === "failure" ? "dashed" : "solid",
    color: relationColor[message.kind],
    targetMarker: "arrow",
    gap: 2,
  };
});

export default function ModuleFederationRecoverySequence() {
  return (
    <DiagramFrame
      data-showcase-corpus="module-federation-recovery-sequence"
      eyebrow="Runtime recovery · Attempt-scoped delivery"
      title="Retry the deployment graph, not one stale URL"
      description="A recoverable remote failure is a protocol across user intent, host state, runtime classification and one atomic asset base. Connect measures the authored message rows."
      caption="A shared-runtime version mismatch would stop at an incompatible state; it is intentionally not disguised as this retryable transport path."
      className="w-full max-w-[1120px] [--diax-accent:#285d67] [--diax-frame-bg:#ebe9e1] [--diax-frame-radius:2px] [--diax-frame-shadow:none] [--diax-node-bg:#f5f2e9] [--diax-node-border:#b8b5a9] [--diax-node-shadow:none] [--diax-node-text:#202722] [--diax-ui-radius:2px]"
    >
      <RecoveryLegend />

      <section
        className="mt-4 hidden border border-[#b8b5a9] bg-[#f5f2e9] sm:block"
        aria-label="Module federation recovery message sequence"
      >
        <ParticipantHeader />
        <ConnectionSurface relations={relations} pathType="straight" className="grid">
          {messages.map((message, index) => (
            <MessageRow key={message.id} message={message} index={index} />
          ))}
        </ConnectionSurface>
      </section>

      <ol
        data-sequence-transcript
        aria-label="Module federation recovery ordered transcript"
        className="m-0 mt-4 grid list-none border-y border-[#b8b5a9] p-0 sm:sr-only"
      >
        {messages.map((message, index) => (
          <li
            key={message.id}
            data-sequence-transcript-message={message.id}
            className="grid grid-cols-[2.75rem_minmax(0,1fr)] gap-3 border-t border-[#d1cec3] py-3 first:border-t-0"
          >
            <span className="font-mono text-[10px] font-bold text-[#285d67]">
              {String(index + 1).padStart(2, "0")}
            </span>
            <span>
              <strong className="block text-[12px] text-[#202722]">
                {participantLabel(message.from)} → {participantLabel(message.to)} · {message.label}
              </strong>
              <small className="mt-1 block text-[10px] leading-4 text-[#5d6762]">
                {message.detail}
              </small>
            </span>
          </li>
        ))}
      </ol>
    </DiagramFrame>
  );
}

function ParticipantHeader() {
  return (
    <header className="grid grid-cols-[4rem_repeat(4,minmax(0,1fr))] border-b border-[#b8b5a9]">
      <div className="p-3 font-mono text-[9px] font-bold uppercase tracking-[0.1em] text-[#687476]">
        Attempt
      </div>
      {participants.map((participant) => (
        <div
          key={participant.id}
          data-sequence-participant={participant.id}
          className="border-l border-[#b8b5a9] px-3 py-3 text-center"
        >
          <h2 className="m-0 text-[12px] font-semibold text-[#202722]">{participant.label}</h2>
          <p className="m-0 mt-1 font-mono text-[8px] uppercase tracking-[0.08em] text-[#687476]">
            {participant.detail}
          </p>
        </div>
      ))}
    </header>
  );
}

function MessageRow({ message, index }: { message: RecoveryMessage; index: number }) {
  return (
    <div
      data-sequence-message={message.id}
      data-sequence-kind={message.kind}
      className="grid min-h-[72px] grid-cols-[4rem_repeat(4,minmax(0,1fr))] border-t border-[#d1cec3] first:border-t-0"
    >
      <div className="flex items-center justify-center font-mono text-[10px] font-bold text-[#285d67]">
        {String(index + 1).padStart(2, "0")}
      </div>
      {participants.map((participant) => {
        const endpoint = participant.id === message.from || participant.id === message.to;
        return (
          <div key={participant.id} className="relative border-l border-[#c5c2b7]">
            {endpoint ? (
              <span
                {...connectionTarget(endpointId(message.id, participant.id))}
                aria-hidden="true"
                className="absolute top-1/2 left-1/2 z-10 size-2 -translate-x-1/2 -translate-y-1/2 border border-[#f5f2e9] outline outline-1 outline-[#687476]"
                style={{ backgroundColor: relationColor[message.kind] }}
              />
            ) : null}
          </div>
        );
      })}
    </div>
  );
}

function MessageLabel({ index, children }: { index: string; children: ReactNode }) {
  return (
    <span className="inline-flex items-center gap-1.5 border border-[#b8b5a9] bg-[#f5f2e9] px-1.5 py-0.5 font-mono text-[9px] font-semibold whitespace-nowrap text-[#35453f]">
      <span className="text-[#285d67]">{index}</span>
      {children}
    </span>
  );
}

function RecoveryLegend() {
  return (
    <ul
      aria-label="Federation recovery message legend"
      className="m-0 grid list-none border-y border-[#b8b5a9] p-0 text-[10px] text-[#5d6762] sm:grid-cols-4"
    >
      <LegendItem label="Request" color={relationColor.request} />
      <LegendItem label="Return" color={relationColor.return} dashed />
      <LegendItem label="Retryable failure" color={relationColor.failure} dashed />
      <LegendItem label="New attempt" color={relationColor.retry} />
    </ul>
  );
}

function LegendItem({
  label,
  color,
  dashed = false,
}: {
  label: string;
  color: string;
  dashed?: boolean;
}) {
  return (
    <li className="flex items-center gap-2 px-3 py-2 sm:border-l sm:first:border-l-0">
      <span
        aria-hidden="true"
        className={`w-8 border-t-2 ${dashed ? "border-dashed" : ""}`}
        style={{ borderColor: color }}
      />
      {label}
    </li>
  );
}

function participantIndex(id: ParticipantId): number {
  return participants.findIndex((participant) => participant.id === id);
}

function participantLabel(id: ParticipantId): string {
  return participants.find((participant) => participant.id === id)?.label ?? id;
}

function endpointId(messageId: string, participantId: ParticipantId): string {
  return `${messageId}-${participantId}`;
}
